// World, cameras and placements solved from the team's keyframes (metres; x along the street, y up, z toward the
// street; origin = centre of the COMPANY door at pavement level on the facade). pc = 16:9 keyframes, hp = 9:16.
// Generated by tools/camera-solve (prep.py); see prototype/k0-k2/HANDOFF.md for the solve and its error.
import type { Vec3 } from "../../core/kit";
import raw from "./data.json";
import type { KeyName } from "./timing";

export type { KeyName };
export type Cam = { pos: Vec3; quat: [number, number, number, number]; fov: number };
export type Fmt = "pc" | "hp";
type PerFmt<T> = Record<Fmt, T>;

export type HomeData = {
  ext: Record<string, number>;
  int: PerFmt<Record<string, number>>;
  intOffset: PerFmt<Vec3>;
  cams: PerFmt<Record<KeyName, Cam>>;
  heru: { k1: Vec3; height: number };
  figs: Record<"sinta" | "bayu" | "nadia" | "fajar" | "dewi", { x: number; z: number; head: number; seated: boolean }>;
  heruK2: PerFmt<Vec3>;
  /** [x, y, z, width] per cloud / bird. */
  clouds: PerFmt<[number, number, number, number][]>;
  birds: PerFmt<[number, number, number, number][]>;
  /** Outline of the COMPANY letters (Nunito ExtraBold), from tools/camera-solve/glyphs.mjs. */
  glyphs: { word: string; bbox: [number, number, number, number]; cmds: (string | number)[][] };
};

export const DATA = raw as unknown as HomeData;
